mapper.select:
SELECT dimension,reported FROM agent_runtime_budget_attempt_amounts
WHERE tenant_id=#{tenant} AND attempt_id=#{attempt} AND dimension IN
#{a.dimension}

mapper.update:
UPDATE agent_runtime_budget_attempt_amounts b SET reported=a.reported
FROM (VALUES

    (#{a.dimension}::text,#{a.reported}::bigint)
) AS a(dimension,reported)
WHERE b.tenant_id=#{tenant} AND b.attempt_id=#{attempt}
  AND b.dimension=a.dimension AND b.reported IS NULL
